/**
 * 생성 파일 — 손으로 고치지 않는다. `pnpm gen:images`(`scripts/gen-images.ts`)가 OG 틀(홈 h1 + 실제 콘솔 화면 조각, 가짜 API 시나리오
 * `landing`)을 헤드리스 Chrome 으로 찍어 만든다. import 는 없다(값 파일). OG 는 1200×630 PNG(언어별). 홈 사진은 `photo-data.ts`.
 */

export interface SiteImage {
  readonly path: string;
  readonly contentType: string;
  readonly width: number;
  readonly height: number;
  readonly hash: string;
  readonly bytes: number;
  readonly base64: string;
}

